"""Data model and calculations for a kitty.

All money is handled as whole cents (ints) internally, so totals always add up
exactly. Amounts are stored in kitty.json as two-decimal strings.
"""

import csv
import datetime
import json
import os
import re
import tempfile
from decimal import Decimal, InvalidOperation, ROUND_HALF_UP
from fractions import Fraction

FILENAME = "kitty.json"
FORMAT_VERSION = 1
CENT = Decimal("0.01")


class KittyError(Exception):
    """A problem caused by user input or the state of the kitty file."""


# ---------------------------------------------------------------- parsing


def parse_decimal(text, what):
    try:
        value = Decimal(text.strip())
    except (InvalidOperation, AttributeError):
        raise KittyError("%s must be a number, got %r" % (what, text))
    if not value.is_finite():
        raise KittyError("%s must be a number, got %r" % (what, text))
    return value


def parse_money(text, what="amount", allow_zero=False):
    """Parse a money amount into whole cents."""
    value = parse_decimal(text, what)
    if value < 0 or (value == 0 and not allow_zero):
        raise KittyError("%s must be greater than zero, got %r" % (what, text))
    if value != value.quantize(CENT):
        raise KittyError("%s can have at most two decimals, got %r" % (what, text))
    return int(value * 100)


def parse_currency(text):
    code = text.strip().upper()
    if not re.fullmatch(r"[A-Z]{3}", code):
        raise KittyError("currency must be a three-letter code like EUR or USD, got %r" % text)
    return code


def parse_date(text):
    try:
        return datetime.date.fromisoformat(text.strip()).isoformat()
    except ValueError:
        raise KittyError("date must look like 2026-07-14, got %r" % text)


def parse_name(text):
    name = text.strip()
    if not name:
        raise KittyError("name cannot be empty")
    if "," in name or "=" in name:
        raise KittyError("name cannot contain ',' or '=', got %r" % text)
    return name


def parse_id(text):
    try:
        value = int(text)
    except ValueError:
        raise KittyError("expense ID must be a whole number, got %r" % text)
    return value


def fmt(cents):
    """Format whole cents as a two-decimal string, e.g. -2070 -> "-20.70"."""
    sign = "-" if cents < 0 else ""
    cents = abs(cents)
    return "%s%d.%02d" % (sign, cents // 100, cents % 100)


def to_cents(text):
    """Read a two-decimal string from kitty.json back into cents."""
    return int(Decimal(text) * 100)


def allocate(total, weights):
    """Split `total` cents in proportion to `weights` (a list of Fractions).

    Uses the largest-remainder method so the parts always add up to `total`.
    Ties go to whoever comes first.
    """
    weight_sum = sum(weights)
    exact = [Fraction(total) * w / weight_sum for w in weights]
    parts = [int(x) for x in exact]  # floor, since everything is >= 0
    leftover = total - sum(parts)
    order = sorted(range(len(weights)), key=lambda i: (-(exact[i] - parts[i]), i))
    for i in order[:leftover]:
        parts[i] += 1
    return parts


# ---------------------------------------------------------------- storage


class Kitty:
    def __init__(self, data, path):
        self.data = data
        self.path = path

    # --- file handling

    @classmethod
    def create(cls, currency, directory="."):
        path = os.path.join(directory, FILENAME)
        if os.path.exists(path):
            raise KittyError("%s already exists here; delete it first to start over" % FILENAME)
        data = {
            "version": FORMAT_VERSION,
            "currency": parse_currency(currency),
            "members": [],
            "rates": {},
            "next_id": 1,
            "next_seq": 1,
            "expenses": [],
            "payments": [],
        }
        kitty = cls(data, path)
        kitty.save()
        return kitty

    @classmethod
    def load(cls, directory="."):
        path = os.path.join(directory, FILENAME)
        if not os.path.exists(path):
            raise KittyError("no %s in this folder; run 'init CURRENCY' first" % FILENAME)
        try:
            with open(path, encoding="utf-8") as f:
                data = json.load(f)
        except (OSError, ValueError) as e:
            raise KittyError("could not read %s: %s" % (FILENAME, e))
        if not isinstance(data, dict) or data.get("version") != FORMAT_VERSION:
            raise KittyError("%s is not a kitty file this version understands" % FILENAME)
        return cls(data, path)

    def save(self):
        # Write to a temporary file first so a crash never leaves a half-written kitty.
        directory = os.path.dirname(os.path.abspath(self.path))
        fd, tmp = tempfile.mkstemp(dir=directory, prefix=".kitty-", suffix=".tmp")
        try:
            with os.fdopen(fd, "w", encoding="utf-8") as f:
                json.dump(self.data, f, indent=2, ensure_ascii=False)
                f.write("\n")
            os.replace(tmp, self.path)
        except BaseException:
            if os.path.exists(tmp):
                os.remove(tmp)
            raise

    # --- helpers

    @property
    def currency(self):
        return self.data["currency"]

    @property
    def members(self):
        return self.data["members"]

    def require_member(self, name):
        name = parse_name(name)
        if name not in self.members:
            raise KittyError("%r is not in the group (members: %s)"
                             % (name, ", ".join(self.members) or "none yet"))
        return name

    def to_base(self, cents, currency):
        if currency == self.currency:
            return cents
        rate = self.data["rates"].get(currency)
        if rate is None:
            raise KittyError("no exchange rate for %s; run 'rate set %s RATE' first"
                             % (currency, currency))
        base = (Decimal(cents) * Decimal(rate)).quantize(Decimal(1), rounding=ROUND_HALF_UP)
        return int(base)

    def next_seq(self):
        seq = self.data["next_seq"]
        self.data["next_seq"] = seq + 1
        return seq

    # --- members

    def add_member(self, name):
        name = parse_name(name)
        if name in self.members:
            raise KittyError("%r is already in the group" % name)
        self.members.append(name)

    def remove_member(self, name):
        name = self.require_member(name)
        for e in self.data["expenses"]:
            if e["payer"] == name or name in e["shares"]:
                raise KittyError("%s is part of expense %d; remove that expense first"
                                 % (name, e["id"]))
        for p in self.data["payments"]:
            if name in (p["from"], p["to"]):
                raise KittyError("%s is part of a payment on %s, so they can't be removed"
                                 % (name, p["date"]))
        self.members.remove(name)

    # --- rates

    def set_rate(self, currency, rate_text):
        currency = parse_currency(currency)
        if currency == self.currency:
            raise KittyError("%s is the main currency, so it doesn't need a rate" % currency)
        rate = parse_decimal(rate_text, "rate")
        if rate <= 0:
            raise KittyError("rate must be greater than zero, got %r" % rate_text)
        self.data["rates"][currency] = str(rate)

    # --- expenses

    def _parse_pairs(self, text, option):
        pairs = []
        seen = set()
        for item in text.split(","):
            if "=" not in item:
                raise KittyError("%s expects NAME=VALUE pairs separated by commas, got %r"
                                 % (option, item))
            name, value = item.split("=", 1)
            name = self.require_member(name)
            if name in seen:
                raise KittyError("%s lists %s more than once" % (option, name))
            seen.add(name)
            pairs.append((name, value.strip()))
        return pairs

    def _split_weights(self, amount, among=None, exact=None, shares=None, percent=None):
        """Work out who shares an expense and in what proportions."""
        chosen = [opt for opt in (among, exact, shares, percent) if opt is not None]
        if len(chosen) > 1:
            raise KittyError("use only one of --among, --exact, --shares, --percent")

        if exact is not None:
            pairs = self._parse_pairs(exact, "--exact")
            weights = [(n, parse_money(v, "--exact amount for %s" % n, allow_zero=True))
                       for n, v in pairs]
            total = sum(w for _, w in weights)
            if total != amount:
                raise KittyError("--exact amounts add up to %s but the expense is %s"
                                 % (fmt(total), fmt(amount)))
        elif shares is not None:
            pairs = self._parse_pairs(shares, "--shares")
            weights = []
            for n, v in pairs:
                w = parse_decimal(v, "--shares value for %s" % n)
                if w < 0:
                    raise KittyError("--shares value for %s can't be negative" % n)
                weights.append((n, w))
        elif percent is not None:
            pairs = self._parse_pairs(percent, "--percent")
            weights = []
            for n, v in pairs:
                w = parse_decimal(v, "--percent value for %s" % n)
                if w < 0:
                    raise KittyError("--percent value for %s can't be negative" % n)
                weights.append((n, w))
            total = sum(w for _, w in weights)
            if total != 100:
                raise KittyError("--percent values must add up to 100, got %s" % total)
        else:
            if among is not None:
                names = [self.require_member(n) for n in among.split(",")]
                if len(set(names)) != len(names):
                    raise KittyError("--among lists someone more than once")
            else:
                names = list(self.members)
                if not names:
                    raise KittyError("the group has no members yet; use 'member add NAME'")
            weights = [(n, 1) for n in names]

        weights = [(n, Fraction(w)) for n, w in weights if w != 0]
        if not weights:
            raise KittyError("the expense has to be split between at least one person")
        return weights

    def add_expense(self, payer, amount, description, among=None, exact=None,
                    shares=None, percent=None, currency=None, date=None, category=None):
        payer = self.require_member(payer)
        amount = parse_money(amount)
        currency = parse_currency(currency) if currency else self.currency
        date = parse_date(date) if date else datetime.date.today().isoformat()
        category = (category or "other").strip().lower()
        if not category:
            raise KittyError("category cannot be empty")
        description = description.strip()
        if not description:
            raise KittyError("description cannot be empty")

        weights = self._split_weights(amount, among, exact, shares, percent)
        base = self.to_base(amount, currency)
        parts = allocate(base, [w for _, w in weights])

        expense_id = self.data["next_id"]
        self.data["next_id"] = expense_id + 1
        self.data["expenses"].append({
            "id": expense_id,
            "seq": self.next_seq(),
            "date": date,
            "payer": payer,
            "description": description,
            "amount": fmt(amount),
            "currency": currency,
            "base_amount": fmt(base),
            "category": category,
            "shares": {n: fmt(c) for (n, _), c in zip(weights, parts)},
        })
        return expense_id

    def remove_expense(self, expense_id):
        expense_id = parse_id(expense_id)
        for i, e in enumerate(self.data["expenses"]):
            if e["id"] == expense_id:
                del self.data["expenses"][i]
                return
        raise KittyError("there is no expense with ID %d" % expense_id)

    def list_expenses(self):
        keys = ["id", "date", "payer", "description", "amount", "currency",
                "base_amount", "category", "shares"]
        return [{k: e[k] for k in keys} for e in self.data["expenses"]]

    # --- payments

    def add_payment(self, sender, receiver, amount, currency=None, date=None):
        sender = self.require_member(sender)
        receiver = self.require_member(receiver)
        if sender == receiver:
            raise KittyError("a payment needs two different people")
        amount = parse_money(amount)
        currency = parse_currency(currency) if currency else self.currency
        date = parse_date(date) if date else datetime.date.today().isoformat()
        self.data["payments"].append({
            "seq": self.next_seq(),
            "date": date,
            "from": sender,
            "to": receiver,
            "amount": fmt(amount),
            "currency": currency,
            "base_amount": fmt(self.to_base(amount, currency)),
        })

    # --- reports

    def _events(self):
        """Every expense and payment as (date, seq, {name: description}, {name: change in cents}).

        Descriptions are per person so payments read from each side's point of view.
        """
        events = []
        for e in self.data["expenses"]:
            changes = {}
            changes[e["payer"]] = to_cents(e["base_amount"])
            for name, share in e["shares"].items():
                changes[name] = changes.get(name, 0) - to_cents(share)
            descriptions = {name: e["description"] for name in changes}
            events.append((e["date"], e["seq"], descriptions, changes))
        for p in self.data["payments"]:
            cents = to_cents(p["base_amount"])
            descriptions = {p["from"]: "Payment to %s" % p["to"],
                            p["to"]: "Payment from %s" % p["from"]}
            events.append((p["date"], p["seq"], descriptions,
                           {p["from"]: cents, p["to"]: -cents}))
        events.sort(key=lambda ev: (ev[0], ev[1]))
        return events

    def balance_cents(self):
        totals = {name: 0 for name in self.members}
        for _, _, _, changes in self._events():
            for name, cents in changes.items():
                totals[name] = totals.get(name, 0) + cents
        return totals

    def balances(self):
        return {name: fmt(c) for name, c in self.balance_cents().items()}

    def settle(self):
        """Suggest payments that bring everyone to zero.

        Repeatedly has the person who owes the most pay the person who is owed
        the most, which keeps the number of payments small.
        """
        order = {name: i for i, name in enumerate(self.members)}
        balances = self.balance_cents()
        debtors = [[-c, n] for n, c in balances.items() if c < 0]
        creditors = [[c, n] for n, c in balances.items() if c > 0]
        transfers = []
        while debtors and creditors:
            debtors.sort(key=lambda d: (-d[0], order.get(d[1], 0)))
            creditors.sort(key=lambda c: (-c[0], order.get(c[1], 0)))
            debt, creditor = debtors[0], creditors[0]
            amount = min(debt[0], creditor[0])
            transfers.append({"from": debt[1], "to": creditor[1], "amount": fmt(amount)})
            debt[0] -= amount
            creditor[0] -= amount
            debtors = [d for d in debtors if d[0] > 0]
            creditors = [c for c in creditors if c[0] > 0]
        return transfers

    def history(self, name):
        name = self.require_member(name)
        running = 0
        rows = []
        for date, _, descriptions, changes in self._events():
            if name not in changes:
                continue
            running += changes[name]
            rows.append({
                "date": date,
                "description": descriptions[name],
                "change": fmt(changes[name]),
                "balance": fmt(running),
            })
        return rows

    def report(self):
        order = {name: i for i, name in enumerate(self.members)}
        totals = {}
        for e in self.data["expenses"]:
            per_person = totals.setdefault(e["category"], {})
            for name, share in e["shares"].items():
                per_person[name] = per_person.get(name, 0) + to_cents(share)
        return {
            category: {n: fmt(c) for n, c in sorted(people.items(),
                                                    key=lambda item: order.get(item[0], 0))}
            for category, people in sorted(totals.items())
        }

    def export_csv(self, filename):
        columns = ["id", "date", "payer", "description", "amount", "currency",
                   "category", "base_amount"]
        try:
            with open(filename, "w", newline="", encoding="utf-8") as f:
                writer = csv.writer(f)
                writer.writerow(columns)
                for e in self.data["expenses"]:
                    writer.writerow([e[c] for c in columns])
        except OSError as e:
            raise KittyError("could not write %s: %s" % (filename, e.strerror or e))
"""Command-line interface: `python3 -m kitty COMMAND ...`."""

import argparse
import json
import sys

from kitty.core import Kitty, KittyError


class Parser(argparse.ArgumentParser):
    """An ArgumentParser that exits with status 1 on bad input (argparse uses 2)."""

    def error(self, message):
        self.print_usage(sys.stderr)
        sys.stderr.write("error: %s\n" % message)
        sys.exit(1)


def build_parser():
    parser = Parser(prog="python3 -m kitty",
                    description="Track shared costs and work out who owes whom.")
    commands = parser.add_subparsers(dest="command", metavar="COMMAND", parser_class=Parser)
    commands.required = True

    p = commands.add_parser("init", help="start a new kitty")
    p.add_argument("currency", help="main currency, e.g. EUR")

    member = commands.add_parser("member", help="add, remove or list members")
    member_cmds = member.add_subparsers(dest="action", metavar="ACTION", parser_class=Parser)
    member_cmds.required = True
    member_cmds.add_parser("add", help="add a member").add_argument("name")
    member_cmds.add_parser("remove", help="remove a member").add_argument("name")
    member_cmds.add_parser("list", help="list members")

    expense = commands.add_parser("expense", help="add, remove or list expenses")
    expense_cmds = expense.add_subparsers(dest="action", metavar="ACTION", parser_class=Parser)
    expense_cmds.required = True
    p = expense_cmds.add_parser("add", help="record an expense")
    p.add_argument("payer")
    p.add_argument("amount")
    p.add_argument("description", nargs="+")
    p.add_argument("--among", metavar="A,B", help="split equally between only these people")
    p.add_argument("--exact", metavar="A=30,B=20", help="split by exact amounts")
    p.add_argument("--shares", metavar="A=2,B=1", help="split by shares")
    p.add_argument("--percent", metavar="A=60,B=40", help="split by percentages")
    p.add_argument("--currency", help="currency it was paid in (default: main currency)")
    p.add_argument("--date", help="date as YYYY-MM-DD (default: today)")
    p.add_argument("--category", help='category (default: "other")')
    expense_cmds.add_parser("list", help="list expenses")
    expense_cmds.add_parser("remove", help="remove an expense").add_argument("id")

    payment = commands.add_parser("payment", help="record a payment between members")
    payment_cmds = payment.add_subparsers(dest="action", metavar="ACTION", parser_class=Parser)
    payment_cmds.required = True
    p = payment_cmds.add_parser("add", help="record that FROM paid TO")
    p.add_argument("sender", metavar="FROM")
    p.add_argument("receiver", metavar="TO")
    p.add_argument("amount")
    p.add_argument("--currency", help="currency it was paid in (default: main currency)")
    p.add_argument("--date", help="date as YYYY-MM-DD (default: today)")

    rate = commands.add_parser("rate", help="set exchange rates")
    rate_cmds = rate.add_subparsers(dest="action", metavar="ACTION", parser_class=Parser)
    rate_cmds.required = True
    p = rate_cmds.add_parser("set", help="one CURRENCY is worth RATE of the main currency")
    p.add_argument("currency")
    p.add_argument("rate")

    commands.add_parser("balances", help="show who is up or down")
    commands.add_parser("settle", help="suggest payments to even everything out")
    commands.add_parser("history", help="everything that affected one person").add_argument("name")
    commands.add_parser("report", help="each person's share of spending per category")
    commands.add_parser("export", help="save expenses to a CSV file").add_argument("file")
    return parser


def output(value):
    print(json.dumps(value, ensure_ascii=False))


def run(args):
    if args.command == "init":
        Kitty.create(args.currency)
        return

    kitty = Kitty.load()
    command = (args.command, getattr(args, "action", None))

    if command == ("member", "add"):
        kitty.add_member(args.name)
        kitty.save()
    elif command == ("member", "remove"):
        kitty.remove_member(args.name)
        kitty.save()
    elif command == ("member", "list"):
        output(kitty.members)
    elif command == ("expense", "add"):
        expense_id = kitty.add_expense(
            args.payer, args.amount, " ".join(args.description),
            among=args.among, exact=args.exact, shares=args.shares, percent=args.percent,
            currency=args.currency, date=args.date, category=args.category)
        kitty.save()
        print(expense_id)
    elif command == ("expense", "list"):
        output(kitty.list_expenses())
    elif command == ("expense", "remove"):
        kitty.remove_expense(args.id)
        kitty.save()
    elif command == ("payment", "add"):
        kitty.add_payment(args.sender, args.receiver, args.amount,
                          currency=args.currency, date=args.date)
        kitty.save()
    elif command == ("rate", "set"):
        kitty.set_rate(args.currency, args.rate)
        kitty.save()
    elif command == ("balances", None):
        output(kitty.balances())
    elif command == ("settle", None):
        output(kitty.settle())
    elif command == ("history", None):
        output(kitty.history(args.name))
    elif command == ("report", None):
        output(kitty.report())
    elif command == ("export", None):
        kitty.export_csv(args.file)
    else:  # pragma: no cover - argparse only lets known commands through
        raise KittyError("unknown command")


def main(argv=None):
    args = build_parser().parse_args(argv)
    try:
        run(args)
    except KittyError as e:
        sys.stderr.write("error: %s\n" % e)
        return 1
    return 0
